SELECT r.id, r.app_id, r.workspace_id, r.channel_id, r.root_thread_ts, r.event_id, r.author_id, r.message_ts, r.query_text, r.has_attachments, r.binding_id, r.access_mode, r.principal_id, r.owner_id, r.request_id, r.turn_id, r.state, r.result_text, r.reason, r.attempts, r.next_attempt_at, r.created_at, r.updated_at, r.query_started_at, r.poll_attempts, r.poll_ready, r.message_surface FROM (SELECT * FROM  (SELECT * FROM inbox_jobs j)  jobs) r WHERE $criteria.CompositeIn("r", $WriterKeys)